{
  "kind": "circuit",
  "schema": {
    "$defs": {
      "Instance": {
        "additionalProperties": false,
        "properties": {
          "component": {
            "description": "Registered compact model name, e.g. 'waveguide', 'mmi1x2', or 'sparams:<file>'.",
            "title": "Component",
            "type": "string"
          },
          "settings": {
            "additionalProperties": true,
            "title": "Settings",
            "type": "object"
          }
        },
        "required": [
          "component"
        ],
        "title": "Instance",
        "type": "object"
      },
      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "A netlist of components with S-parameter models; solves the circuit S-matrix.",
    "properties": {
      "kind": {
        "const": "circuit",
        "default": "circuit",
        "title": "Kind",
        "type": "string"
      },
      "instances": {
        "additionalProperties": {
          "$ref": "#/$defs/Instance"
        },
        "title": "Instances",
        "type": "object"
      },
      "connections": {
        "description": "Pairs of 'instance,port'.",
        "items": {
          "maxItems": 2,
          "minItems": 2,
          "prefixItems": [
            {
              "type": "string"
            },
            {
              "type": "string"
            }
          ],
          "type": "array"
        },
        "title": "Connections",
        "type": "array"
      },
      "ports": {
        "additionalProperties": {
          "type": "string"
        },
        "description": "External port name -> 'instance,port'.",
        "title": "Ports",
        "type": "object"
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
            "$ref": "#/$defs/WavelengthRange"
          }
        ],
        "title": "Wavelengths"
      },
      "options": {
        "additionalProperties": {
          "additionalProperties": true,
          "type": "object"
        },
        "title": "Options",
        "type": "object"
      }
    },
    "required": [
      "instances",
      "ports",
      "wavelengths"
    ],
    "title": "CircuitProblem",
    "type": "object"
  },
  "conventions": "Lightsmith conventions (fixed; changing them needs a schema version bump):\n- Lengths in nm. Wavelengths are vacuum wavelengths in nm.\n- Time dependence exp(-i omega t): absorbing materials have Im(eps) > 0 and Im(n) > 0.\n- Cross sections in nm^2; efficiencies Q = C / (pi r_eq^2), r_eq = volume-equivalent radius of all particles.\n- layer_stack / periodic: layers listed from the superstrate (incidence side) to the substrate; light travels +z.\n  R is measured in the superstrate, T in the substrate.\n- mode: cross-section in the xy plane, propagation along +z.\n- device: ports are planes whose normal is the axis where size_nm is zero; direction is into the device.\n- problem.options[<method or backend name>] holds solver options, validated by that backend.\n- Materials: {\"kind\": \"constant_index\", \"n_real\": .., \"n_imag\": ..}, {\"kind\": \"library\", \"name\": \"Au\"},\n  drude, drude_lorentz, tabulated, constant_permittivity. FDTD needs dispersive models (fit_drude_lorentz).\n- Results carry provenance and warnings: read the warnings before trusting the numbers.\n",
  "backends": [
    {
      "name": "lightsmith-circuit",
      "method": "circuit",
      "available": true,
      "gpu": true,
      "auto_rank": 0
    }
  ],
  "example": {
    "kind": "circuit",
    "instances": {
      "split": {
        "component": "coupler",
        "settings": {
          "coupling": 0.5
        }
      },
      "combine": {
        "component": "coupler",
        "settings": {
          "coupling": 0.5
        }
      },
      "long": {
        "component": "waveguide",
        "settings": {
          "length_nm": 120000,
          "neff": 2.4,
          "ng": 4.2
        }
      },
      "short": {
        "component": "waveguide",
        "settings": {
          "length_nm": 100000,
          "neff": 2.4,
          "ng": 4.2
        }
      }
    },
    "connections": [
      [
        "split,o3",
        "long,o1"
      ],
      [
        "long,o2",
        "combine,o2"
      ],
      [
        "split,o4",
        "short,o1"
      ],
      [
        "short,o2",
        "combine,o1"
      ]
    ],
    "ports": {
      "in1": "split,o1",
      "in2": "split,o2",
      "out1": "combine,o3",
      "out2": "combine,o4"
    },
    "wavelengths": {
      "start_nm": 1500,
      "stop_nm": 1600,
      "num": 201
    }
  }
}

